use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn main () -> Result < () > { println ! ("🎨 RECURSIVE EMOJI COMPRESSION SYSTEM") ; println ! ("====================================") ; let emoji_map_content = fs :: read_to_string ("emoji_subexpression_map.json") ? ; let original_vocab : HashMap < String , String > = serde_json :: from_str (& emoji_map_content) ? ; println ! ("📥 Loaded {} original patterns" , original_vocab . len ()) ; let compression_result = recursive_compress (original_vocab) ? ; println ! ("\n🎯 COMPRESSION SUMMARY:") ; println ! ("======================") ; println ! ("Original patterns: {}" , compression_result . original_patterns) ; println ! ("Final vocab size: {}" , compression_result . final_vocab_size) ; println ! ("Total compression ratio: {:.4}" , compression_result . total_compression) ; println ! ("Compression layers: {}" , compression_result . layers . len ()) ; println ! ("\n📊 LAYER BREAKDOWN:") ; for layer in & compression_result . layers { println ! ("Layer {}: {} tokens (ratio: {:.3})" , layer . layer , layer . vocab . len () , layer . compression_ratio) ; } let output = serde_json :: to_string_pretty (& compression_result) ? ; fs :: write ("recursive_emoji_compression.json" , output) ? ; println ! ("\n💾 Saved recursive compression to recursive_emoji_compression.json") ; let final_layer = compression_result . layers . last () . unwrap () ; println ! ("\n🔥 FINAL ULTRA-COMPRESSED VOCABULARY:") ; println ! ("====================================") ; for (emoji , pattern) in final_layer . vocab . iter () . take (20) { println ! ("{} = {}" , emoji , pattern) ; } Ok (()) }